<template>
 <view class="detail-overlay" @click.self="$emit('close')" @keydown.esc.stop="$emit('close')"><view ref="dialog" class="detail-dialog" role="dialog" aria-modal="true" :aria-label="$t(&quot;ui.published_listing_details&quot;)" tabindex="-1" @keydown.tab="trapFocus"><view class="detail-head"><view><b>{{ $t("ui.published_listing_details") }}</b><view class="meta"><text class="status">{{$t(statusLabel)}}</text><text>{{created}}</text></view><text class="caption">{{ $t("ui.these_are_your_published_conditions") }}</text></view><button tabindex="0" class="close" :aria-label="$t(&quot;ui.close_listing_details&quot;)" @click="$emit('close')">×</button></view><view class="detail-body"><view v-for="row in rows" :key="row.key" class="detail-row"><text class="detail-key">{{row.label}}</text><view class="tags"><text v-for="(value,index) in row.values" :key="index">{{value}}</text><text v-if="!row.values.length">{{ $t("ui.not_entered") }}</text></view></view></view><view class="detail-footer"><button tabindex="0" @click="$emit('close')">{{ $t("action.close") }}</button></view></view></view>
</template>
<script setup>
import {t,formatDate} from '../i18n/index.js'
import {computed,ref,nextTick,onMounted,onBeforeUnmount} from 'vue'
import {publishedRecruitmentDetails} from '../utils/recruitment-comparison.js'
const props=defineProps({ticket:{type:Object,required:true}})
defineEmits(['close'])
const dialog=ref(null),rows=computed(()=>publishedRecruitmentDetails(props.ticket.profile))
const statusLabel=computed(()=>({waiting:'status.recruiting',matched:'ui.teammate_found',expired:'ui.expired',cancelled:'ui.cancelled',replaced:'ui.replaced',done:'ui.completed'}[props.ticket.status]||'ui.listing_ended'))
const created=computed(()=>props.ticket.created?t('message.publishedAt',{time:formatDate(props.ticket.created,{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})}):'')
let lastFocus=null,bodyOverflow='',rootOverflow=''
const element=()=>dialog.value?.$el||dialog.value
onMounted(async()=>{if(typeof document==='undefined')return;lastFocus=document.activeElement;bodyOverflow=document.body.style.overflow;rootOverflow=document.documentElement.style.overflow;document.body.style.overflow='hidden';document.documentElement.style.overflow='hidden';await nextTick();element()?.focus()})
onBeforeUnmount(()=>{if(typeof document!=='undefined'){document.body.style.overflow=bodyOverflow;document.documentElement.style.overflow=rootOverflow;lastFocus?.focus?.()}})
function trapFocus(event){const nodes=[...element().querySelectorAll('[tabindex="0"]')];const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===element())){event.preventDefault();last.focus()}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===element())){event.preventDefault();first.focus()}}
</script>
<style scoped>
.detail-overlay{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:20px;background:#03070bdb;backdrop-filter:blur(7px)}.detail-dialog{display:flex;flex-direction:column;width:100%;max-width:620px;max-height:88vh;outline:none;background:#141e2b;color:#d5e1ef;border:1px solid #42536c;border-radius:14px;box-shadow:0 25px 90px #0009}.detail-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;padding:19px 22px;border-bottom:1px solid #2d3b4e}.detail-head b{display:block;font-size:17px}.meta{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:9px 0;color:#8ea4be;font-size:10px}.status{padding:2px 6px;background:#b9f4770c;border:1px solid #b9f47740;border-radius:4px;color:#c8e7ac}.caption{color:#93a8bf;font-size:11px}.close{margin:0;border:0;background:none;color:#9cafc6;font-size:24px;padding:0 4px;line-height:1}.detail-body{padding:9px 22px 14px;overflow-y:auto;min-height:0;overscroll-behavior:contain}.detail-row{display:grid;grid-template-columns:76px minmax(0,1fr);gap:12px;padding:12px 0;border-bottom:1px solid #29394c}.detail-row:last-child{border-bottom:0}.detail-key{color:#92a7c0;font-size:11px;line-height:1.8;padding-top:2px}.tags{display:flex;flex-wrap:wrap;gap:6px}.tags>text{font-size:11px;line-height:1.7;padding:2px 7px;color:#c9d7e8;border:1px solid #374c65;background:#101a27;border-radius:4px;overflow-wrap:anywhere}.detail-footer{padding:13px 22px;display:flex;justify-content:flex-end;border-top:1px solid #2d3b4e}.detail-footer button{margin:0;background:#1b2939;color:#c3d3e4;border:1px solid #415771;border-radius:7px;padding:8px 20px;font-size:12px;line-height:1.6}button:focus-visible{outline:2px solid #b9f477;outline-offset:3px}@media(max-width:500px){.detail-overlay{padding:12px}.detail-head,.detail-body,.detail-footer{padding:15px}.detail-row{grid-template-columns:66px minmax(0,1fr);gap:8px}.detail-dialog{max-height:90vh}}
</style>
